import fs from 'node:fs'
import {GLTFLoader} from 'three/addons/loaders/GLTFLoader.js'
import * as T from 'three'
// Load the real rig in Node without browser-only image decoding.
export async function readRig(file = 'spider-walker-ik.glb') {
  const b=fs.readFileSync(new URL(`../public/models/${file}`,import.meta.url))
  const length=b.readUInt32LE(12)
  const json=JSON.parse(b.subarray(20,20+length).toString())
  const start=20+length+8
  json.buffers[0].uri='data:application/octet-stream;base64,'+b.subarray(start,start+json.buffers[0].byteLength).toString('base64')
  delete json.images;delete json.textures;delete json.materials
  for(const mesh of json.meshes)for(const p of mesh.primitives)delete p.material
  globalThis.ProgressEvent??=class ProgressEvent {constructor(type,props){Object.assign(this,{type},props)}}
  return new GLTFLoader().parseAsync(JSON.stringify(json),'')
}
if(process.argv[1]?.endsWith('check-animation.js')) {
  const gltf=await readRig()
  console.log('Clips:',gltf.animations.map(c=>({name:c.name,duration:c.duration,tracks:c.tracks.length})))
  const mixer=new T.AnimationMixer(gltf.scene);mixer.clipAction(gltf.animations[0]).play();mixer.update(0)
  const meshes=[];gltf.scene.traverse(o=>{if(o.isSkinnedMesh)meshes.push(o)})
  const snapshot=()=>{gltf.scene.updateMatrixWorld(true);return meshes.map(m=>{m.skeleton.update();return Array.from(m.skeleton.boneMatrices)})}
  const before=snapshot();mixer.update(.4);const after=snapshot()
  console.log('Skin changes:',before.map((a,i)=>Math.max(...a.map((v,j)=>Math.abs(v-after[i][j])))))
  console.log('Changing tracks:',gltf.animations[0].tracks.filter(t=>t.values.some((v,i)=>Math.abs(v-t.values[i%t.getValueSize()])>.0001)).map(t=>t.name))
}

